const data = $input.first().json.body;

const items = data.offres.map(offre => ({
  json: {
    numero_da: data.numero_da,
    code_article: data.code_article,
    designation: data.designation,
    tarif_systeme: data.tarif_systeme,
    ...offre
  }
}));

return items;

const compareItems = $('Code').all();
const fileItems = $('Read/Write Files from Disk').all();

// ⚠️ Adapte cette URL à ton webhook de validation
const WEBHOOK_BASE = 'http://localhost:8001/api/comparatif/valider-offre';

let sections = '';
const combinedBinary = {};
let binaryIndex = 0;
let hasAnyAttachment = false;

for (const item of compareItems) {
  const data = item.json;

  let matchedFile = null;
  if (data.fichier_joint_url) {
    matchedFile = fileItems.find(f => {
      const binaryData = f.binary ? Object.values(f.binary)[0] : null;
      const fileName = binaryData?.fileName || f.json.fileName || f.json.name || '';
      return fileName.includes(data.fichier_joint_url);
    });
  }

  const validationUrl = `${WEBHOOK_BASE}?numero_da=${encodeURIComponent(data.numero_da)}&code_article=${encodeURIComponent(data.code_article)}&numero_rfq=${encodeURIComponent(data.numero_rfq)}&code_fournisseur=${encodeURIComponent(data.code_fournisseur)}`;

  // Ajoute la/les pièce(s) jointe(s) de ce devis au binary combiné
  if (matchedFile && matchedFile.binary) {
    for (const key of Object.keys(matchedFile.binary)) {
      const newKey = `attachment_${binaryIndex}`;
      combinedBinary[newKey] = matchedFile.binary[key];
      binaryIndex++;
      hasAnyAttachment = true;
    }
  }

  sections += `
    <div style="border:1px solid #ddd; border-radius:6px; padding:12px; margin-bottom:20px;">
      <table style="border-collapse: collapse; width: 100%;">
        <tr><td style="padding:4px;"><b>N° DA</b></td><td style="padding:4px;">${data.numero_da}</td></tr>
        <tr><td style="padding:4px;"><b>Article</b></td><td style="padding:4px;">${data.code_article} - ${data.designation}</td></tr>
        <tr><td style="padding:4px;"><b>Fournisseur</b></td><td style="padding:4px;">${data.nom_fournisseur} (${data.code_fournisseur})</td></tr>
        <tr><td style="padding:4px;"><b>N° RFQ</b></td><td style="padding:4px;">${data.numero_rfq}</td></tr>
        <tr><td style="padding:4px;"><b>Marque souhaitée</b></td><td style="padding:4px;">${data.marque_souhaitee || 'Non spécifiée'}</td></tr>
        <tr><td style="padding:4px;"><b>Marque proposée</b></td><td style="padding:4px;">${data.marque_proposee || 'Non spécifiée'}</td></tr>
        <tr><td style="padding:4px;"><b>Prix proposé</b></td><td style="padding:4px;">${data.prix_unitaire_ht} ${data.devise}</td></tr>
        <tr><td style="padding:4px;"><b>Tarif système</b></td><td style="padding:4px;">${data.tarif_systeme} MAD</td></tr>
      </table>

      <p>${matchedFile ? "Le devis fournisseur est joint à cet email." : "Aucun devis joint n'a été fourni pour cette offre."}</p>

      <p style="text-align:center; margin: 16px 0;">
        <a href="${validationUrl}" style="background-color:#28a745; color:#ffffff; padding:10px 20px; text-decoration:none; border-radius:5px; display:inline-block; font-weight:bold;">
          ✅ Valider ce devis
        </a>
      </p>
    </div>
  `;
}

const subject = `Validation Comparatifs - ${compareItems.length} devis à valider`;

const htmlBody = `
  <p>Bonjour Monsieur le Président Directeur Général,</p>

  <p>Veuillez trouver ci-dessous les comparatifs à valider :</p>

  ${sections}

  <p>Cordialement.</p>
`;

return [
  {
    json: {
      subject,
      message: htmlBody,
      hasAttachment: hasAnyAttachment
    },
    binary: hasAnyAttachment ? combinedBinary : undefined
  }
];
